#!/bin/sh
# Sanitize output filename: whitelist [A-Za-z0-9._-], percent-encode rest.
# Rejects path traversal, NUL, DEL, unicode normalization attacks.
sanitize_filename() {
    _in="$1"
    [ -z "$_in" ] && { printf '%s' 'index.html'; return 0; }
    # strip fragment
    _in="${_in%%#*}"
    # reject empty after strip
    [ -z "$_in" ] && { printf '%s' 'index.html'; return 0; }
    _out=''
    _i=0
    _len=${#_in}
    while [ "$_i" -lt "$_len" ]; do
        _c=$(printf '%s' "$_in" | cut -c $((_i+1)))
        case "$_c" in
            [A-Za-z0-9._-]) _out="${_out}${_c}" ;;
            *)
                # percent-encode byte
                _hex=$(printf '%s' "$_c" | od -An -tx1 | tr -d ' \n')
                _out="${_out}%${_hex}"
                ;;
        esac
        _i=$((_i+1))
    done
    # reject leading dot-dot or absolute
    case "$_out" in
        ..*|/*) printf '%s' 'index.html' ;;
        *) printf '%s' "$_out" ;;
    esac
}
